import { buildBaseMediaResponseHeaders } from './buildBaseMediaResponseHeaders.js';
import { getMediaType } from './getMediaType.js';
import { shouldAttachMedia } from './shouldAttachMedia.js';
const FORWARDED_MEDIA_RESPONSE_HEADERS = [
    'Cache-Control',
    'Content-Length',
    'Content-Range',
    'ETag',
    'Last-Modified'
];
const ATTACHMENT_CSP = "sandbox; default-src 'none'; base-uri 'none'; form-action 'none'";
export function buildMediaResponseHeaders({ filename, upstreamHeaders }) {
    const headers = buildBaseMediaResponseHeaders();
    for (const name of FORWARDED_MEDIA_RESPONSE_HEADERS){
        const value = upstreamHeaders.get(name);
        if (value) {
            headers.set(name, value);
        }
    }
    if (shouldAttachMedia(upstreamHeaders)) {
        headers.set('Content-Type', 'application/octet-stream');
        headers.set('Content-Disposition', attachmentDisposition(filename));
        headers.set('Content-Security-Policy', ATTACHMENT_CSP);
    } else {
        // Send only the approved media type; do not pass through untrusted parameters.
        headers.set('Content-Type', getMediaType(upstreamHeaders));
    }
    return headers;
}
function attachmentDisposition(filename) {
    const sanitizedName = sanitizeFilename(filename);
    const safeName = Array.from(sanitizedName).slice(0, 255).join('') || 'download';
    let utf8Name;
    try {
        // encodeURIComponent leaves !, ', (, ), and * unchanged. Encode those five characters as % escapes.
        utf8Name = encodeURIComponent(safeName).replace(/[!'()*]/g, (character)=>`%${character.charCodeAt(0).toString(16).toUpperCase()}`);
    } catch  {
        // Invalid UTF-16, such as an unpaired surrogate, cannot be encoded in filename*.
        return `attachment; filename="download"; filename*=UTF-8''download`;
    }
    // Replace non-ASCII and control characters, quotes, backslashes, and % with underscores.
    const asciiName = safeName.replace(/[^\x20-\x7e]/g, '_').replace(/["\\%]/g, '_');
    return `attachment; filename="${asciiName}"; filename*=UTF-8''${utf8Name}`;
}
function sanitizeFilename(filename) {
    // Replace control characters (0–31 and 127) and slashes with underscores.
    // This keeps newlines and directory paths out of the download name.
    return Array.from(filename, (character)=>{
        const codePoint = character.codePointAt(0);
        return codePoint < 32 || codePoint === 127 || character === '/' || character === '\\' ? '_' : character;
    }).join('');
}
